-- First production programme catalogue milestone: 100 current English-taught
-- programmes from official 2026/27 university catalogues. Catalogue presence is
-- separate from verified admission rules; every imported record remains unverified.

alter table public.programmes
  add column if not exists official_programme_code text,
  add column if not exists degree_class text,
  add column if not exists catalogue_source_url text,
  add column if not exists catalogue_checked_at date,
  add column if not exists duration_years numeric(3,1);

create unique index if not exists programmes_official_code_year_idx
  on public.programmes (university_id, official_programme_code, academic_year)
  where official_programme_code is not null;

