insert into public.programmes (
  university_id, university_name, programme_name, country_code, city,
  degree_level, teaching_language, intake, source_url, application_url,
  academic_year, verification_status, verification_notes, requirements,
  official_programme_code, degree_class, catalogue_source_url,
  catalogue_checked_at, duration_years
)
select
  university.id,
  catalogue.university_name,
  catalogue.programme_name,
  'IT',
  catalogue.city,
  catalogue.degree_level,
  catalogue.teaching_language,
  'Fall 2026',
  catalogue.source_url,
  catalogue.source_url,
  '2026/27',
  'unverified',
  'Official catalogue entry. Admission requirements, fees and deadlines still require human verification against the programme call.',
  '{}'::jsonb,
  catalogue.official_programme_code,
  catalogue.degree_class,
  catalogue.source_url,
  date '2026-09-23',
  case catalogue.degree_level when 'Bachelor' then 3 when 'Master' then 2 else null end
from catalogue
join public.universities university on university.slug = catalogue.university_slug
on conflict (university_name, programme_name, academic_year) do update set
  university_id = excluded.university_id,
  city = excluded.city,
  degree_level = excluded.degree_level,
  teaching_language = excluded.teaching_language,
  source_url = excluded.source_url,
  application_url = excluded.application_url,
  official_programme_code = excluded.official_programme_code,
  degree_class = excluded.degree_class,
  catalogue_source_url = excluded.catalogue_source_url,
  catalogue_checked_at = excluded.catalogue_checked_at,
  duration_years = excluded.duration_years,
  updated_at = now();

comment on column public.programmes.catalogue_checked_at is
  'Date the programme presence and basic catalogue metadata were checked; this does not verify admission rules.';
